 1	method findMax(a:array<int>) returns (pos:int, maxVal: int)
 2	  requires a.Length > 0;
 3	  requires forall i :: 0 <= i < a.Length ==> a[i] >= 0;
 4	  ensures forall i :: 0 <= i < a.Length ==> a[i] <= maxVal;
 5	  ensures exists i :: 0 <= i < a.Length &&  a[i] == maxVal;
 6	  ensures 0 <= pos < a.Length
 7	  ensures a[pos] == maxVal;
 8	{
 9	  pos := 0;
10	  maxVal := a[0];
11	  var j := 1;
12	  while(j < a.Length)
13	    invariant 1 <= j <= a.Length;
14	    invariant forall i :: 0 <= i < (j) - 1 ==> a[i] <= maxVal;
15	    invariant exists i :: 0 <= i < j && a[i] == maxVal;
16	    invariant 0 <= pos < a.Length;
17	    invariant a[pos] == maxVal;
18	  {
19	    if (a[j] > maxVal) 
20	    {
21	      maxVal := a[j];
22	      pos := j;
23	    }
24	    j := j+1;
25	  }
26	  return;
27	}

